/**
 * Every key a supported tag decodes has a zod counterpart of a type that tag
 * can decode — and every zod key is one some supported tag decodes.
 *
 * The fixture is `src/core-keys.json`, generated by `bun run core-keys
 * <Xray-core clone>` from every tag's own `infra/conf` (struct tags, plus what
 * the core does with each raw field). The walk itself is `scripts/walk.ts`. A
 * gap kept on purpose goes in ALLOWED with the reason; an entry that no longer
 * matches a gap fails too, so the list only shrinks.
 *
 * `CORE_KEYS_REPORT=1 bun test coverage` prints every finding.
 */
import { describe, expect, it } from 'bun:test';
import versions from '../versions.json' with { type: 'json' };
import { CUSTOM, fixture, walk } from '../scripts/walk.js';

/**
 * Gaps kept on purpose → why. A key is either `Struct.key`, for a gap
 * wherever that struct is met, or the finding's path (starting with "."),
 * when the struct is shared and only one place is meant — WireGuardConfig
 * serves both directions, and only the inbound leaves out the client's keys.
 *
 * Most are keys a tag refuses or never reads. They stay out of the schema
 * because a schema is also what an editor offers to complete; objects stay
 * open, so a config that already holds one is not condemned for it.
 * (The Xray Config UI Editor's per-version table is what reports them.)
 */
const ALLOWED: Record<string, string> = {
    // --- refused at load -------------------------------------------------
    'Config.transport': 'A non-empty global transport fails the load on every tag.',
    'TrojanUserConfig.flow': 'Any non-empty flow on a trojan client fails the load on every tag.',
    '.inbounds[].settings<vless>.clients[].encryption': 'Refused on an inbound user: "encryption should not be in inbound settings" (v26.10.21:infra/conf/vless.go:84-86); the inbound has `decryption`.',
    '.outbounds[].settings<vless>.vnext[].users[].reverse': "Refused in vnext: “please use simplified outbound's config style to use reverse” (v26.10.21:infra/conf/vless.go:313-322); the flat `reverse` is in the schema.",
    'TLSConfig.verifyPeerCertInNames': '26.3 refuses any value and later tags dropped the key; see TlsSchema.',
    'KCPConfig.header': '26.3 and 26.7 refuse it outright, 26.9 on decode and never read it; see MkcpTransportSchema.',
    'KCPConfig.seed': 'As header; see MkcpTransportSchema.',
    'HysteriaConfig.congestion': '26.3/26.7 decode it, warn that it moved to finalmask.quicParams and never use it; 26.9 removed it.',
    'HysteriaConfig.up': 'As congestion — moved to finalmask.quicParams.brutalUp.',
    'HysteriaConfig.down': 'As congestion — moved to finalmask.quicParams.brutalDown.',
    'HysteriaConfig.udphop': 'As congestion — moved to the udphop finalmask.',

    // --- decoded, never read ---------------------------------------------
    'RawFieldRule.type': "No supported tag reads a rule's `type` (RouterRule: v26.10.21:infra/conf/router.go:127-131); kept because published configs and generators write `field`, which loads.",
    'WireGuardConfig.IsClient': 'The loader sets it itself for each direction (v26.10.21:infra/conf/xray.go, the registries); not configuration.',
    'VLessUser.xorMode': 'A vless.Account field Build() derives from the encryption string (v26.10.21:infra/conf/vless.go:340-370); not configuration.',
    'VLessUser.seconds': 'As xorMode.',
    'VLessUser.padding': 'As xorMode.',
    '.inbounds[].settings<vless>.clients[].testpre': "Pre-connections are opened by an outbound (proxy/vless/outbound); an inbound user's is never read.",
    '.inbounds[].settings<vmess>.clients[].security': "A VMess server answers in what each client asks for; the account's security is the client's setting.",
    '.inbounds[].settings<vmess>.clients[].experiments': 'As security — a client-side switch.',
    '.inbounds[].settings<wireguard>.noKernelTun': 'Client only: a server is on gVisor whatever it says.',
    '.inbounds[].settings<wireguard>.reserved': 'Client only; Build() still checks it.',
    '.inbounds[].settings<wireguard>.domainStrategy': 'Client only, 26.3 to v26.9.9.',
    '.inbounds[].settings<wireguard>.remoteDNS': 'Client only, 26.9 on.',
    '.outbounds[].settings<wireguard>.peers[].level': "A peer is a user only on an inbound (v26.10.21:infra/conf/wireguard.go:87-113); a client's peer keeps no level.",
    '.outbounds[].settings<wireguard>.peers[].email': 'As level.',
    '.inbounds[].streamSettings.xhttpSettings.extra.host': 'Inside `extra` Build() keeps host, path and mode from the outer object (v26.7.28:infra/conf/transport_method.go:308-315); see XhttpExtraSchema.',
    '.inbounds[].streamSettings.xhttpSettings.extra.path': 'As host.',
    '.inbounds[].streamSettings.xhttpSettings.extra.mode': 'As host.',
    '.inbounds[].streamSettings.xhttpSettings.extra.extra': 'An `extra` inside `extra` is not read again.',

    '.inbounds[].settings<wireguard>.peers[].endpoint': 'A server keeps nothing of it from 26.7; 26.3 passes it on. The inbound schema lists what a server reads on every tag.',
    'ShadowsocksClientConfig.uot': '26.3 only, and declared in the server entry alone on purpose (test/outbound-fields.test.ts).',
    'ShadowsocksClientConfig.uotVersion': 'As uot.',

    // --- one prerelease decoded it differently ----------------------------
    'TunConfig.mtu': 'v26.4.13 alone decodes a list (`MTU []uint32`, v26.4.13:infra/conf/tun.go:10, defaulting to [1500, 1280]); v26.4.15 made it one number again (v26.4.15:infra/conf/tun.go:10) and every other tag agrees. The schema types the number.',

    // --- a second spelling the schema does not type ----------------------
    '.outbounds[].settings<wireguard>.reserved': 'encoding/json also reads a []byte from a base64 string; the schema types only the three numbers, the spelling everyone writes.',
};

describe('zod schemas cover what every tag decodes', () => {
    const { findings } = walk();
    if (process.env.CORE_KEYS_REPORT) {
        for (const f of findings) console.log(`${f.problem.padEnd(7)} ${f.id.padEnd(48)} ${f.path}  — ${f.detail}`);
        console.log(`${findings.length} findings`);
    }

    it('reads the release set versions.json describes', () => {
        expect(fixture.tags[0]).toBe(versions.floor);
        for (const entry of versions.extra) {
            const [tag, commit] = entry.split('@');
            expect(fixture.tags).toContain(tag!);
            expect(fixture.refs[tag!]?.startsWith(commit!)).toBe(true);
        }
        // Each line names a tag in the set; lines are labels, nothing more.
        for (const tag of Object.values(versions.lines)) expect(fixture.tags).toContain(tag);
    });

    it('knows the JSON shape of every type with a decoder of its own', () => {
        expect(fixture.customUnmarshalers.filter(t => !CUSTOM[t])).toEqual([]);
    });

    it('has no gap that is not on the allow-list', () => {
        const unexplained = findings.filter(f => !(f.id in ALLOWED) && !(f.path in ALLOWED)).map(f => `${f.problem} ${f.id} (${f.path}): ${f.detail}`);
        expect(unexplained).toEqual([]);
    });

    it('has no allow-list entry that no longer matches a gap', () => {
        const ids = new Set(findings.flatMap(f => [f.id, f.path]));
        expect(Object.keys(ALLOWED).filter(id => !ids.has(id))).toEqual([]);
    });
});
